// Profile-photo storage under the two-role model: the REAL phase6/20 and phase6/24 policies on embedded Postgres (PGlite) with a storage.objects emulation.
// LOCAL evidence only. storage.objects is emulated (same permissive-policy model as Supabase); signed URLs are generated by the Storage service
// from SELECT permission, so "may read" here is "may create a signed URL". Nothing here ran on staging or production.
import test, { before } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { PGlite } from '@electric-sql/pglite';

const read = (rel) => readFileSync(fileURLToPath(new URL(rel, import.meta.url)), 'utf8').replace(/\r\n/g, '\n');
const db = new PGlite();
const U = {
  admin: 'aaaaaaaa-0000-4000-8000-000000000001', agent: 'aaaaaaaa-0000-4000-8000-000000000002', other: 'aaaaaaaa-0000-4000-8000-000000000003',
  backOffice: 'aaaaaaaa-0000-4000-8000-000000000004', manager: 'aaaaaaaa-0000-4000-8000-000000000005', inactive: 'aaaaaaaa-0000-4000-8000-000000000006',
  inactiveAdmin: 'aaaaaaaa-0000-4000-8000-000000000007',
};
const file = (who) => `${U[who]}/avatar.jpg`;

async function as(who) {
  await db.exec('reset role');
  await db.query("select set_config('request.jwt.claim.sub', $1, false)", [who === 'anon' || !who ? '' : U[who]]);
  if (who === 'anon') await db.exec('set role anon'); else if (who) await db.exec('set role authenticated');
}
const attempt = async (sql, params) => { try { const r = await db.query(sql, params); return { ok: true, n: r.affectedRows ?? r.rows.length, rows: r.rows }; } catch (e) { return { ok: false, err: e.message }; } };
const put = async (who, name, bucket = 'avatars') => { await as(who); return attempt('insert into storage.objects (bucket_id, name) values ($1, $2)', [bucket, name]); };
const see = async (who) => { await as(who); return (await db.query("select name from storage.objects where bucket_id = 'avatars' order by name")).rows.map((r) => r.name); };
const replace = async (who, name) => { await as(who); const r = await attempt("update storage.objects set owner = null where bucket_id = 'avatars' and name = $1", [name]); return r.ok && r.n > 0; };
const remove = async (who, name) => { await as(who); const r = await attempt("delete from storage.objects where bucket_id = 'avatars' and name = $1 returning name", [name]); return r.ok && r.rows.length > 0; };
const seed = async (who) => { await as(null); await db.query("insert into storage.objects (bucket_id, name) values ('avatars', $1) on conflict do nothing", [file(who)]); };

before(async () => {
  await db.exec(`
    create role anon nologin; create role authenticated nologin; create role service_role nologin bypassrls;
    create schema auth;
    create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
    create table public.profiles (id uuid primary key, role text not null, is_active boolean not null default true);
    -- The two-role definitions (phase6/21, phase6/23): legacy roles are not staff.
    create function public.is_staff() returns boolean language sql stable security definer set search_path to 'public'
      as $$ select exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_active and p.role in ('admin', 'inside_sales', 'field_sales')) $$;
    create function public.is_role(r text) returns boolean language sql stable security definer set search_path = public
      as $$ select exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_active and p.role = r) $$;
    insert into public.profiles (id, role, is_active) values ('${U.admin}', 'admin', true), ('${U.agent}', 'field_sales', true), ('${U.other}', 'field_sales', true), ('${U.backOffice}', 'back_office', true),
      ('${U.manager}', 'manager', true), ('${U.inactive}', 'field_sales', false), ('${U.inactiveAdmin}', 'admin', false);
    create table auth.users (id uuid primary key);
    create schema storage;
    create table storage.buckets (id text primary key, name text, public boolean default false, file_size_limit bigint, allowed_mime_types text[]);
    create table storage.objects (id uuid primary key default gen_random_uuid(), bucket_id text not null references storage.buckets(id), name text not null, owner uuid, unique (bucket_id, name));
    create function storage.foldername(name text) returns text[] language sql immutable
      as $$ select (string_to_array(name, '/'))[1:array_length(string_to_array(name, '/'), 1) - 1] $$;
    alter table storage.objects enable row level security;
    grant usage on schema storage, public to anon, authenticated;
    grant select, insert, update, delete on storage.objects to anon, authenticated;
    insert into storage.buckets (id, name, public) values ('hlektrismos_docs', 'hlektrismos_docs', false);
  `);
});

test('BEFORE: production has no avatars bucket, so the upload cannot work (the reported "not available" message)', async () => {
  assert.equal((await db.query("select count(*)::int n from storage.buckets where id = 'avatars'")).rows[0].n, 0);
  assert.equal((await put('agent', file('agent'))).ok, false);
});

test('phase6/20 alone reproduces the defect: a legacy back_office can read every photo', async () => {
  await as(null);
  await db.exec(read('../staged-migrations/phase6/20_user_preferences.sql'));
  await seed('agent'); await seed('other');
  assert.deepEqual(await see('backOffice'), [file('agent'), file('other')].sort(), 'the legacy role reads everyone: the defect');
  assert.ok((await db.query("select 1 from pg_policies where policyname = 'avatars read office'")).rows.length === 1);
});

test('phase6/24 applies twice (idempotent) and replaces the office policy with an Admin-only one', async () => {
  await as(null);
  const sql = read('../staged-migrations/phase6/24_avatars_admin_only_read.sql');
  await db.exec(sql); await db.exec(sql);
  const names = (await db.query("select policyname from pg_policies where schemaname = 'storage' and tablename = 'objects' and policyname like 'avatars %' order by 1")).rows.map((r) => r.policyname);
  assert.deepEqual(names, ['avatars read admin', 'avatars read own', 'avatars remove own', 'avatars replace own', 'avatars write own']);
  assert.equal(names.length, 5, 'still the five policies the migration check counts');
  const q = (await db.query("select qual from pg_policies where policyname = 'avatars read admin'")).rows[0].qual;
  assert.ok(!/back_office|manager/.test(q), 'no legacy role in the policy text');
});

test('phase6/24 is self-contained: on a database that never had phase6/20 it creates the bucket and the policies', async () => {
  const fresh = new PGlite();
  await fresh.exec(`create role authenticated nologin; create role anon nologin; create schema auth; create schema storage;
    create function auth.uid() returns uuid language sql as 'select null::uuid';
    create function public.is_staff() returns boolean language sql as 'select false'; create function public.is_role(r text) returns boolean language sql as 'select false';
    create table storage.buckets (id text primary key, name text, public boolean default false, file_size_limit bigint, allowed_mime_types text[]);
    create table storage.objects (id uuid primary key default gen_random_uuid(), bucket_id text, name text, owner uuid);
    create function storage.foldername(name text) returns text[] language sql immutable as $$ select (string_to_array(name, '/'))[1:array_length(string_to_array(name, '/'), 1) - 1] $$;
    alter table storage.objects enable row level security;`);
  await fresh.exec(read('../staged-migrations/phase6/24_avatars_admin_only_read.sql'));
  assert.equal((await fresh.query("select count(*)::int n from storage.buckets where id = 'avatars' and not public")).rows[0].n, 1);
  assert.equal((await fresh.query("select count(*)::int n from pg_policies where policyname like 'avatars %'")).rows[0].n, 5);
});

test('private bucket configuration: not public, 512 KB, JPEG only; and a processed 256x256 JPEG is far under the limit', async () => {
  const b = (await db.query("select public, file_size_limit, allowed_mime_types from storage.buckets where id = 'avatars'")).rows[0];
  assert.equal(b.public, false);
  assert.equal(Number(b.file_size_limit), 524288);
  assert.deepEqual(b.allowed_mime_types, ['image/jpeg']);
  assert.ok(256 * 256 * 3 < Number(b.file_size_limit), 'even an uncompressed 256x256 RGB image is smaller than the limit, so any JPEG the browser produces fits');
  await as(null);
  await db.exec("update storage.buckets set public = true, file_size_limit = 1 where id = 'avatars'");
  await db.exec(read('../staged-migrations/phase6/24_avatars_admin_only_read.sql'));
  const again = (await db.query("select public, file_size_limit from storage.buckets where id = 'avatars'")).rows[0];
  assert.equal(again.public, false, 'a public bucket is made private again'); assert.equal(Number(again.file_size_limit), 524288);
});

test('own photo: upload, replace, remove, and read (= signed URL) work for a Sales Agent', async () => {
  await as(null); await db.exec("delete from storage.objects where bucket_id = 'avatars'");
  assert.equal((await put('agent', file('agent'))).ok, true, 'upload');
  assert.equal(await replace('agent', file('agent')), true, 'replace');
  assert.deepEqual(await see('agent'), [file('agent')], 'read');
  assert.equal(await remove('agent', file('agent')), true, 'remove');
  assert.deepEqual(await see('agent'), []);
});

test('cross-user: a Sales Agent cannot upload as, replace, remove or read another user\'s photo', async () => {
  await seed('other');
  assert.equal((await put('agent', file('other'))).ok, false, 'upload into someone else\'s folder');
  assert.equal(await replace('agent', file('other')), false, 'replace');
  assert.equal(await remove('agent', file('other')), false, 'remove');
  assert.deepEqual(await see('agent'), [], 'read: sees nothing of the other agent');
  await as(null); assert.equal((await db.query("select count(*)::int n from storage.objects where name = $1", [file('other')])).rows[0].n, 1, 'the file is untouched');
});

test('only the exact path is accepted: another file name, a nested folder or another bucket is refused', async () => {
  for (const name of [`${U.agent}/avatar.png`, `${U.agent}/other.jpg`, `${U.agent}/x/avatar.jpg`, 'avatar.jpg', `${U.other}/avatar.jpg`]) assert.equal((await put('agent', name)).ok, false, name);
});

test('Admin reads staff avatars (needed to show staff photos) but cannot write, replace or delete them', async () => {
  await seed('agent'); await seed('other');
  assert.deepEqual(await see('admin'), [file('agent'), file('other')].sort());
  assert.equal((await put('admin', file('agent') + '.x')).ok, false);
  assert.equal(await replace('admin', file('agent')), false);
  assert.equal(await remove('admin', file('agent')), false);
});

test('legacy back_office and manager hold no extra read permission (the defect is closed)', async () => {
  assert.deepEqual(await see('backOffice'), [], 'back_office');
  assert.deepEqual(await see('manager'), [], 'manager');
  assert.equal((await put('backOffice', file('backOffice'))).ok, false, 'a legacy role is not staff, so it cannot even write its own');
});

test('inactive accounts cannot upload, replace, remove or read, including an inactive Admin', async () => {
  await seed('inactive');
  assert.equal((await put('inactive', file('inactive') + 'x')).ok, false);
  assert.deepEqual(await see('inactive'), [], 'inactive agent reads nothing, not even its own');
  assert.equal(await replace('inactive', file('inactive')), false);
  assert.equal(await remove('inactive', file('inactive')), false);
  assert.deepEqual(await see('inactiveAdmin'), [], 'an inactive Admin reads nothing');
});

test('anonymous has no access at all, and the service role is not needed by the browser', async () => {
  assert.deepEqual(await see('anon'), []);
  assert.equal((await put('anon', file('agent') + 'z')).ok, false);
  assert.equal(await replace('anon', file('agent')), false);
  assert.equal(await remove('anon', file('agent')), false);
});

test('rollback removes the Admin read and never restores the back_office read; own access stays', async () => {
  await as(null);
  await db.exec(read('../../docs/ops/rollback_phase6_24_avatars_admin_only_read.sql'));
  const names = (await db.query("select policyname from pg_policies where policyname like 'avatars %' order by 1")).rows.map((r) => r.policyname);
  assert.ok(!names.includes('avatars read office') && !names.includes('avatars read admin'));
  assert.deepEqual(await see('backOffice'), []);
  assert.deepEqual(await see('admin'), [], 'Admin loses the staff-photo read');
  assert.deepEqual(await see('agent'), [file('agent')], 'own photo still readable');
});

test('the browser code: private signed URLs only, path pinned to the user, only the user\'s own profile row, no service key', () => {
  const src = readFileSync(fileURLToPath(new URL('../../src/lib/avatar.ts', import.meta.url)), 'utf8');
  assert.match(src, /export const avatarPath = \(userId: string\) => `\$\{userId\}\/avatar\.jpg`/);
  assert.match(src, /createSignedUrl\(path, SIGNED_SECONDS\)/);
  assert.ok(!/getPublicUrl|service_role|SERVICE_ROLE|secret/i.test(src), 'no public URL and no privileged key in the browser');
  assert.match(src, /\^\[0-9a-f-\]\{36\}\\\/avatar\\\.jpg\$/, 'a stored path that is not {uuid}/avatar.jpg is never signed');
  const page = readFileSync(fileURLToPath(new URL('../../src/components/app/CustomizePage.tsx', import.meta.url)), 'utf8');
  assert.match(page, /updateProfile\(profile\.id, \{ avatar_url: res\.path \}\)/, 'only the signed-in user\'s own row');
});
